using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Sends an upgraded gift that is available for resale to another user or channel chat; gifts already owned by the current user
    /// must be transferred using transferGift and can't be passed to the method
    /// </summary>
    public Task<TdLib.TdApi.Objects.GiftResaleResult> SendResoldGiftAsync(string giftName = default, MessageSender ownerId = default, GiftResalePrice price = default)
    {

           using var activity =  StartCallActivity("SendResoldGiftAsync", typeof(SendResoldGift).FullName ?? "SendResoldGiftAsync");

           try
           {
             return client.SendResoldGiftAsync(giftName, ownerId, price);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
